rm -rf /tmp/noteschk && mkdir -p /tmp/noteschk && cp cli.py /tmp/noteschk/ && cat > /tmp/noteschk/notes.py <<'EOF'
import json, os
def _load(path):
    p = path or "notes.json"
    if not os.path.exists(p):
        return []
    with open(p, encoding="utf-8") as f:
        data = json.load(f)
    if not isinstance(data, list):
        raise ValueError("notes.json does not contain a list of notes")
    return data
def _save(items, path):
    p = path or "notes.json"
    tmp = p + ".tmp"
    with open(tmp, "w", encoding="utf-8") as f:
        json.dump(items, f, ensure_ascii=False, indent=2)
    os.replace(tmp, p)
def add(text, path=None):
    text = (text or "").strip()
    if not text:
        raise ValueError("note text must not be empty")
    items = _load(path); items.append(text); _save(items, path)
    return len(items)
def list(path=None):
    return _load(path)
def delete(number, path=None):
    items = _load(path)
    if not items:
        raise ValueError("no notes to delete")
    if number < 1 or number > len(items):
        raise IndexError(f"no note {number}; there are {len(items)} notes")
    removed = items.pop(number - 1); _save(items, path)
    return removed
EOF
cd /tmp/noteschk && python3 cli.py --help; echo "=== add help ==="; python3 cli.py add --help; echo "=== delete help ==="; python3 cli.py delete --help; echo "=== list help ==="; python3 cli.py list --help
